-- MORE SAMPLE DATA for demonstration: more cities, stays, vehicles, ratings, and one pending stay and bus for the admin to approve.
-- Run db/seed_sample.sql first is NOT required; this file stands alone. Safe to run more than once.
-- Remove all sample data (this file and seed_sample.sql) with db/remove_sample.sql.
--   docker compose -f docker-compose.prod.yml exec -T db psql -U roomly -d roomly < db/seed_sample_more.sql
CREATE EXTENSION IF NOT EXISTS pgcrypto;
ON CONFLICT (email) DO NOTHING;

